// 搜索结果页样式（v1.7.0 度量重构，纯 RN 基准）
// 改动说明：删 var() 兜底与 padding-bottom hack；尺寸走 dp token；行高落 dp；
// 全部独立类名（RN 忽略组合/分组选择器）。
@import '../../styles/_rn';

// ============ 搜索输入行 ============
.search-input-wrap {
  display: flex;
  flex-direction: row;
  align-items: center;
  height: $search-box-height;
  background: $bg-card;
  border-radius: $radius-lg;
  padding-left: $space-3;
  padding-right: $space-3;
  margin: $space-3 $space-4 0 $space-4;
}

.search-input {
  flex: 1;
  min-width: 0;
  font-size: $font-size-md;
  line-height: $line-height-md;
  color: $text-primary;
  margin-left: $space-2;
}

// ============ 加载态 ============
.loading {
  display: flex;
  align-items: center;
  justify-content: center;
  padding-top: $space-8;
  padding-bottom: $space-8;
}

.loading-text {
  font-size: $font-size-md;
  line-height: $line-height-md;
  color: $text-tertiary;
}

// ============ 结果列表 ============
.result-list {
  margin: $space-3 $space-4;
}

.result-count {
  font-size: $font-size-sm;
  line-height: $line-height-sm;
  color: $text-tertiary;
  margin-bottom: $space-2;
}

.result-item {
  display: flex;
  flex-direction: row;
  align-items: center;
  background: $bg-card;
  border-radius: $radius-lg;
  padding: $card-padding;
  margin-bottom: $space-2;
}

.result-icon {
  width: 40px;
  height: 40px;
  border-radius: $radius-md;
  background: $primary-light;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-right: $space-3;
}

.result-info {
  flex: 1;
  min-width: 0;
}

.result-name {
  font-size: $font-size-lg;
  line-height: $line-height-lg;
  color: $text-primary;
  font-weight: bold;
}

.result-brand {
  font-size: $font-size-sm;
  line-height: $line-height-sm;
  color: $text-secondary;
  margin-top: 2px;
}

.result-specs {
  display: flex;
  flex-direction: row;
  margin-top: $space-1;
}

.spec {
  font-size: $font-size-xs;
  line-height: $line-height-xs;
  color: $text-tertiary;
  background: $bg-input;
  border-radius: $radius-sm;
  padding-top: 2px;
  padding-bottom: 2px;
  padding-left: $space-2;
  padding-right: $space-2;
  margin-right: $space-2;
}

// ============ 空状态 ============
.empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding-top: 80px;
}

.empty-text {
  font-size: $font-size-md;
  line-height: $line-height-md;
  color: $text-secondary;
  margin-top: $space-4;
}

.empty-hint {
  font-size: $font-size-sm;
  line-height: $line-height-sm;
  color: $text-tertiary;
  margin-top: $space-2;
}

// ============ 分类 Tab ============
.search-tabs {
  display: flex;
  flex-direction: row;
  border-bottom-width: 1px;
  border-bottom-style: solid;
  margin-top: $space-3;
}

.search-tab {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding-top: $space-3;
  padding-bottom: $space-2;
}

.search-tab-text {
  color: $text-secondary;
}

.search-tab-underline {
  width: 24px;
  height: 3px;
  border-radius: 999px;
  margin-top: $space-2;
}

// 结果缩略图（有图时）
.result-thumb {
  width: 40px;
  height: 40px;
  border-radius: $radius-md;
}

// ============ 品牌/类型引用行 ============
.ref-row {
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  border-radius: $radius-lg;
  padding: $card-padding;
  margin-bottom: $space-2;
}

.ref-name {
  font-weight: bold;
}

// 品牌/类型行副提示
.ref-hint {
  margin-left: $space-2;
  flex: 1;
}

// ============ 排序栏 ============
.sort-bar {
  display: flex;
  flex-direction: row;
  align-items: center;
  height: 40px;
  padding-left: $space-3;
  padding-right: $space-3;
  border-bottom-width: 1px;
  border-bottom-style: solid;
}

.sort-item {
  flex-direction: row;
  align-items: center;
  margin-right: $space-4;
}

.sort-filter-btn {
  flex-direction: row;
  align-items: center;
  margin-left: auto;
}

// ============ 已选筛选 chips ============
.filter-chips {
  flex-direction: row;
  flex-wrap: wrap;
  padding-left: $space-4;
  padding-right: $space-4;
  padding-top: $space-2;
}

.chip {
  flex-direction: row;
  align-items: center;
  border-radius: 999px;
  padding-top: 4px;
  padding-bottom: 4px;
  padding-left: $space-2;
  padding-right: $space-2;
  margin-right: $space-2;
  margin-bottom: $space-2;
}

.chip-text {
  margin-right: 4px;
}

// ============ 尺寸筛选面板 ============
.filter-panel {
  margin: $space-2 $space-4;
  border-radius: $radius-lg;
  padding: $space-4;
}

.filter-panel-title {
  font-weight: bold;
  margin-bottom: $space-3;
}

.filter-range-row {
  flex-direction: row;
  align-items: center;
  margin-bottom: $space-3;
}

.filter-range-label {
  width: 44px;
}

.filter-range-input {
  flex: 1;
  height: 36px;
  border-radius: $radius-md;
  padding-left: $space-2;
  padding-right: $space-2;
  font-size: $font-size-md;
}

.filter-range-dash {
  margin-left: $space-2;
  margin-right: $space-2;
}

.filter-panel-actions {
  flex-direction: row;
  justify-content: flex-end;
  margin-top: $space-2;
}

.filter-reset {
  height: 36px;
  border-width: 1px;
  border-style: solid;
  border-radius: $radius-lg;
  padding-left: $space-5;
  padding-right: $space-5;
  align-items: center;
  justify-content: center;
  margin-right: $space-3;
}

.filter-apply {
  height: 36px;
  border-radius: $radius-lg;
  padding-left: $space-5;
  padding-right: $space-5;
  align-items: center;
  justify-content: center;
}

// 轴承行内尺寸
.result-specs-inline {
  margin-top: 2px;
}

// 加载更多
.load-more {
  align-items: center;
  justify-content: center;
  padding-top: $space-4;
  padding-bottom: $space-4;
}

// 加载失败重试按钮
.retry-btn {
  margin-top: $space-4;
  height: 40px;
  padding-left: $space-6;
  padding-right: $space-6;
  border-radius: $radius-lg;
  display: flex;
  align-items: center;
  justify-content: center;
}

.retry-btn-text {
  font-weight: bold;
}
